  sol=least_squares(f,np.clip(q,self.limits[:,0]+.0001,self.limits[:,1]-.0001),bounds=(self.limits[:,0]+.00001,self.limits[:,1]-.00001),max_nfev=100,xtol=1e-9,ftol=1e-9,gtol=1e-9)
